// ===== eingebettet aus src/fehlerklassen.js – nicht hier bearbeiten, sondern im Repo (npm run build) =====
const fehlerklassen = (() => {
const module = { exports: {} };
// Fehlerklassen und Statuscode-Mapping (Masterprompt 3, Bauplan 3).
// EPA-Fehler werden als Text "[EPA:<status>:<CODE>:<Vorgangs-ID|->] <Meldung>" geworfen,
// damit der Error-Handler (EPA-05) sie aus execution.error.message zurücklesen kann.

const FEHLERCODES = Object.freeze({
	UNGUELTIGES_FORMAT: { status: 400, klasse: 'Eingabe', retrybar: false },
	UNGUELTIGER_AUSLOESER: { status: 400, klasse: 'Eingabe', retrybar: false },
	UNBEKANNTER_STATUS: { status: 400, klasse: 'Eingabe', retrybar: false },
	AUTH_FEHLER: { status: 401, klasse: 'Authentifizierung', retrybar: false },
	KEINE_BERECHTIGUNG: { status: 403, klasse: 'Authentifizierung', retrybar: false },
	VORGANG_NICHT_GEFUNDEN: { status: 404, klasse: 'Nicht gefunden', retrybar: false },
	KONFIG_NICHT_GEFUNDEN: { status: 404, klasse: 'Konfiguration', retrybar: false },
	NICHT_GEFUNDEN: { status: 404, klasse: 'Nicht gefunden', retrybar: false },
	DUPLIKAT: { status: 409, klasse: 'Konflikt', retrybar: false },
	UNZULAESSIGER_STATUSWECHSEL: { status: 409, klasse: 'Konflikt', retrybar: false },
	UNZULAESSIGER_AUSLOESER: { status: 409, klasse: 'Konflikt', retrybar: false },
	VERSIONSKONFLIKT: { status: 409, klasse: 'Konflikt', retrybar: true },
	GESPERRT: { status: 409, klasse: 'Konflikt', retrybar: true },
	KONFIG_MEHRDEUTIG: { status: 409, klasse: 'Konfiguration', retrybar: false },
	FREIGABE_ABGELAUFEN: { status: 410, klasse: 'Freigabe', retrybar: false },
	EXTRAKTION_UNGUELTIG: { status: 422, klasse: 'LLM', retrybar: false },
	KONFIGURATIONSFEHLER: { status: 424, klasse: 'Konfiguration', retrybar: false },
	RATE_LIMIT: { status: 429, klasse: 'Upstream', retrybar: true },
	UPSTREAM_FEHLER: { status: 502, klasse: 'Upstream', retrybar: true },
	NICHT_ERREICHBAR: { status: 503, klasse: 'Upstream', retrybar: true },
	ZEITUEBERSCHREITUNG: { status: 504, klasse: 'Upstream', retrybar: true },
	UNBEKANNT: { status: 500, klasse: 'Unbekannt', retrybar: false },
});

// Bei diesen Codes bearbeitet eine andere Ausführung den Vorgang bzw. die Mail ist schon verarbeitet:
// der Vorgang wird NICHT auf "Eskaliert / Manuell" gesetzt (sonst würde ein Parallellauf gestört).
const OHNE_ESKALATION = Object.freeze(['VERSIONSKONFLIKT', 'GESPERRT', 'DUPLIKAT']);

const EPA_MUSTER = /^\[EPA:(\d{3}):([A-Z_]+):([^\]]*)\]\s*([\s\S]*)$/;

function formatEpaFehler(code, vorgangsId, meldung) {
	const def = FEHLERCODES[code] || FEHLERCODES.UNBEKANNT;
	return `[EPA:${def.status}:${FEHLERCODES[code] ? code : 'UNBEKANNT'}:${vorgangsId || '-'}] ${meldung || ''}`.trim();
}

/** Wirft einen EPA-Fehler (für Code-Nodes). */
function epaFehler(code, vorgangsId, meldung) {
	const err = new Error(formatEpaFehler(code, vorgangsId, meldung));
	err.epaCode = code;
	return err;
}

function parseEpaFehler(text) {
	if (typeof text !== 'string') return null;
	// n8n stellt der Meldung manchmal Präfixe voran; das Muster darf irgendwo in der ersten Zeile beginnen.
	const start = text.indexOf('[EPA:');
	if (start < 0) return null;
	const m = text.slice(start).match(EPA_MUSTER);
	if (!m) return null;
	return {
		status: Number(m[1]),
		code: m[2],
		vorgangsId: m[3] === '-' ? null : m[3],
		meldung: m[4].trim(),
	};
}

/** Entfernt personenbezogene Daten und kürzt (keine Mail-Inhalte im Fehlerlog). */
function bereinigeMeldung(text, maxLaenge = 300) {
	if (text === undefined || text === null) return '';
	let s = String(text)
		.replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '<email>')
		.replace(/\+?\d[\d\s/().-]{7,}\d/g, '<nummer>')
		.replace(/Bearer\s+[A-Za-z0-9._~+/=-]+/g, 'Bearer <token>')
		.replace(/\s+/g, ' ')
		.trim();
	if (s.length > maxLaenge) s = s.slice(0, maxLaenge - 1) + '…';
	return s;
}

function codeAusHttpStatus(status) {
	const n = Number(status);
	if (!Number.isFinite(n)) return null;
	if (n === 400 || n === 422) return 'UNGUELTIGES_FORMAT';
	if (n === 401) return 'AUTH_FEHLER';
	if (n === 403) return 'KEINE_BERECHTIGUNG';
	if (n === 404) return 'NICHT_GEFUNDEN';
	if (n === 408 || n === 504) return 'ZEITUEBERSCHREITUNG';
	if (n === 409) return 'DUPLIKAT';
	if (n === 429) return 'RATE_LIMIT';
	if (n === 503) return 'NICHT_ERREICHBAR';
	if (n >= 500 && n < 600) return 'UPSTREAM_FEHLER';
	return null;
}

function codeAusText(text) {
	const t = String(text || '');
	if (/timed? ?out|ETIMEDOUT|ESOCKETTIMEDOUT|timeout of \d+ms/i.test(t)) return 'ZEITUEBERSCHREITUNG';
	if (/ECONNREFUSED|ECONNRESET|ENOTFOUND|EAI_AGAIN|socket hang up|service unavailable/i.test(t)) return 'NICHT_ERREICHBAR';
	if (/rate.?limit|too many requests/i.test(t)) return 'RATE_LIMIT';
	if (/invalid_grant|unauthori[sz]ed|token (has )?expired|invalid.?token|authentication failed|password authentication/i.test(t)) return 'AUTH_FEHLER';
	if (/forbidden|insufficient privileges|access denied|permission denied/i.test(t)) return 'KEINE_BERECHTIGUNG';
	if (/duplicate key|unique constraint/i.test(t)) return 'DUPLIKAT';
	return null;
}

/**
 * Klassifiziert einen Fehler.
 * @param {{message?: string, description?: string, httpCode?: string|number}} fehler
 */
function klassifiziereFehler(fehler) {
	const f = fehler || {};
	const epa = parseEpaFehler(f.message) || parseEpaFehler(f.description);
	let code;
	let vorgangsId = null;
	let meldung;
	if (epa) {
		code = FEHLERCODES[epa.code] ? epa.code : 'UNBEKANNT';
		vorgangsId = epa.vorgangsId;
		meldung = epa.meldung;
	} else {
		code = codeAusHttpStatus(f.httpCode) || codeAusText(`${f.message || ''} ${f.description || ''}`) || 'UNBEKANNT';
		meldung = f.message || f.description || '';
	}
	const def = FEHLERCODES[code];
	return {
		statuscode: def.status,
		fehlercode: code,
		klasse: def.klasse,
		retrybar: def.retrybar,
		eskalieren: !OHNE_ESKALATION.includes(code),
		vorgangsId,
		meldung: bereinigeMeldung(meldung),
	};
}

/**
 * Baut aus der Ausgabe des Error Trigger einen Fehlerlog-Eintrag (ohne Mail-Inhalte).
 * Error Trigger liefert entweder {execution, workflow} oder bei Trigger-Fehlern {trigger, workflow}.
 */
function ausErrorTrigger(json) {
	const j = json || {};
	const exec = j.execution || {};
	const err = exec.error || (j.trigger && j.trigger.error) || {};
	const k = klassifiziereFehler({
		message: err.message,
		description: err.description,
		httpCode: err.httpCode,
	});
	const node = (err.node && err.node.name) || exec.lastNodeExecuted || null;
	const workflow = j.workflow || {};
	return {
		statuscode: k.statuscode,
		fehlercode: k.fehlercode,
		klasse: k.klasse,
		retrybar: k.retrybar,
		eskalieren: k.eskalieren && Boolean(k.vorgangsId),
		workflow_id: workflow.id || null,
		workflow_name: workflow.name || null,
		node,
		execution_id: exec.id !== undefined && exec.id !== null ? String(exec.id) : null,
		execution_url: exec.url || null,
		modus: exec.mode || (j.trigger && j.trigger.mode) || null,
		vorgangs_id: k.vorgangsId,
		meldung: k.meldung,
	};
}

function escapeHtml(s) {
	return String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
}

function alarmHtml(eintrag) {
	const e = eintrag;
	const zeilen = [
		`<b>EPA-Fehler ${e.statuscode} ${escapeHtml(e.fehlercode)}</b> (${escapeHtml(e.klasse)})`,
		`Workflow: ${escapeHtml(e.workflow_name || e.workflow_id || '?')}`,
		`Node: ${escapeHtml(e.node || '?')}`,
		`Vorgang: ${escapeHtml(e.vorgangs_id || '–')}`,
		`Meldung: ${escapeHtml(e.meldung || '–')}`,
		e.retrybar ? 'Hinweis: vorübergehender Fehler, erneuter Versuch kann helfen.' : 'Hinweis: dauerhafter Fehler, bitte prüfen.',
	];
	if (e.execution_url) zeilen.push(`<a href="${escapeHtml(e.execution_url)}">Ausführung ${escapeHtml(e.execution_id)} öffnen</a>`);
	return zeilen.join('<br>');
}

module.exports = {
	FEHLERCODES,
	OHNE_ESKALATION,
	formatEpaFehler,
	epaFehler,
	parseEpaFehler,
	bereinigeMeldung,
	klassifiziereFehler,
	ausErrorTrigger,
	alarmHtml,
	escapeHtml,
};
return module.exports;
})();
// ===== Ende src/fehlerklassen.js =====

// ----- Node-Logik -----
// "jetzt" nur für Tests/manuelle Läufe überschreibbar (Fristen, Geschäftszeit). Der Lock nutzt immer die echte Zeit.
const e = $input.first().json || {};
const echt = new Date().toISOString();
let jetzt = echt;
if (typeof e.jetzt === 'string' && e.jetzt.trim()) {
	if (!Number.isFinite(new Date(e.jetzt).getTime())) throw fehlerklassen.epaFehler('UNGUELTIGES_FORMAT', null, 'Eingabe "jetzt" ist kein gültiger Zeitpunkt');
	jetzt = new Date(e.jetzt).toISOString();
}
return [{ json: { jetzt, echt, lauf_id: String($execution.id) } }];

// ===== eingebettet aus src/nachfassen.js – nicht hier bearbeiten, sondern im Repo (npm run build) =====
const nachfassen = (() => {
const module = { exports: {} };
// Phase E (Masterprompt Workflow 4, Bauplan 2.2/6): Nachfassen beim Kunden, Eskalation, Erinnerung an Freigeber
// und Erneuerung abgelaufener Freigabe-Links. Reine Planungslogik: EPA-04 liest Vorgänge, offene Freigaben und
// Configs, dieses Modul entscheidet, was zu tun ist. Ausgeführt wird jede Aufgabe einzeln in "EPA SW Nachfassen".
// Es wird nie automatisch an Kunden gesendet: Eine Erinnerung an den Kunden ist immer ein Entwurf mit Freigabe.

const LOCK_SCHLUESSEL = 'epa04_lauf';
const LOCK_MINUTEN = 55;
const MAX_AUFGABEN = 50;
const EPOCHE = '1970-01-01T00:00:00.000Z';
const WARTEN = 'Warten auf Kunde';

// Reihenfolge, falls mehr Aufgaben anfallen als ein Lauf abarbeitet (Rest folgt im nächsten Lauf).
const PRIORITAET = Object.freeze({ eskalation: 1, erinnerung: 2, freigabe_erneuern: 3, freigabe_erinnerung: 4 });

function ms(t) {
	if (t === null || t === undefined || t === '') return NaN;
	const x = new Date(t).getTime();
	return Number.isFinite(x) ? x : NaN;
}

/**
 * Plant die Aufgaben eines Laufs.
 * @param {object} p
 * @param {object[]} p.vorgaenge  Zeilen aus epa_vorgaenge (Status "Warten auf Kunde")
 * @param {object[]} p.freigaben  Zeilen aus epa_freigaben (Status "offen")
 * @param {object} p.configs      kunde_id -> geprüfte Config; null = Kunde inaktiv; fehlt = Config ungültig
 * @param {string} p.jetzt        ISO-Zeitpunkt
 * @param {object} p.fristen      Modul src/fristen.js (im Code-Node eingebettet)
 * @returns {{ aufgaben: object[], uebersprungen: object[], verschoben: number }}
 */
function planen({ vorgaenge, freigaben, configs, jetzt, fristen, max = MAX_AUFGABEN }) {
	const jetztMs = ms(jetzt);
	if (!Number.isFinite(jetztMs)) throw new Error(`Ungültiger Zeitpunkt "${jetzt}"`);
	const aufgaben = [];
	const uebersprungen = [];
	const imDienst = {};
	const geschaeftszeit = (kunde, c) => {
		if (!(kunde in imDienst)) imDienst[kunde] = fristen.istGeschaeftszeit(jetzt, c);
		return imDienst[kunde];
	};

	for (const v of vorgaenge || []) {
		if (!v || v.status !== WARTEN) continue;
		const frist = ms(v.antwort_frist);
		if (!Number.isFinite(frist) || frist >= jetztMs) continue;
		const ref = { kunde_id: v.kunde_id, vorgangs_id: v.vorgangs_id };
		const c = configs[v.kunde_id];
		if (!c) {
			uebersprungen.push({ ...ref, grund: c === null ? 'kunde_inaktiv' : 'keine_gueltige_config' });
			continue;
		}
		if (!geschaeftszeit(v.kunde_id, c)) {
			uebersprungen.push({ ...ref, grund: 'ausserhalb_geschaeftszeit' });
			continue;
		}
		const gesendet = Number(v.erinnerungen_gesendet || 0);
		const erlaubt = Number(c.anzahl_erinnerungen || 0);
		aufgaben.push({
			aktion: gesendet < erlaubt ? 'erinnerung' : 'eskalation',
			...ref,
			freigabe_id: '',
			version: v.version ?? null,
			erinnerungen_gesendet: gesendet,
		});
	}

	for (const f of freigaben || []) {
		if (!f || f.status !== 'offen') continue;
		const ref = { kunde_id: f.kunde_id, vorgangs_id: f.vorgangs_id, freigabe_id: f.freigabe_id };
		const c = configs[f.kunde_id];
		if (!c) {
			uebersprungen.push({ ...ref, grund: c === null ? 'kunde_inaktiv' : 'keine_gueltige_config' });
			continue;
		}
		const abgelaufen = ms(f.ablauf) <= jetztMs;
		let erinnern = false;
		if (!abgelaufen && !f.erinnert_am && Number(c.freigabe_erinnerung_stunden) > 0) {
			const basis = f.erneuert_am || f.createdAt;
			if (Number.isFinite(ms(basis))) erinnern = ms(fristen.berechneFrist(new Date(basis).toISOString(), c.freigabe_erinnerung_stunden, c)) <= jetztMs;
		}
		if (!abgelaufen && !erinnern) continue;
		if (!geschaeftszeit(f.kunde_id, c)) {
			uebersprungen.push({ ...ref, grund: 'ausserhalb_geschaeftszeit' });
			continue;
		}
		aufgaben.push({ aktion: abgelaufen ? 'freigabe_erneuern' : 'freigabe_erinnerung', ...ref, version: null, erinnerungen_gesendet: null });
	}

	aufgaben.sort((a, b) => PRIORITAET[a.aktion] - PRIORITAET[b.aktion]);
	return { aufgaben: aufgaben.slice(0, max), uebersprungen, verschoben: Math.max(0, aufgaben.length - max) };
}

// ---------------------------------------------------------------- Lauf-Lock (Tabelle epa_system_status)

function lockHolen(laufId, jetztEcht) {
	const t = ms(jetztEcht);
	return {
		lock_bis: new Date(t + LOCK_MINUTEN * 60000).toISOString(),
		lock_durch: String(laufId),
		letzter_start: new Date(t).toISOString(),
	};
}

function lockFreigeben(jetztEcht, ergebnis) {
	return {
		lock_bis: EPOCHE,
		lock_durch: '',
		letzter_lauf: new Date(ms(jetztEcht)).toISOString(),
		letztes_ergebnis: JSON.stringify(ergebnis || {}),
	};
}

/** Zusammenfassung eines Laufs, nur Zähler und IDs (keine personenbezogenen Daten). */
function laufAuswerten(plan, ergebnisse) {
	const zaehler = {};
	const fehler = [];
	(plan.aufgaben || []).forEach((a, i) => {
		const r = (ergebnisse || [])[i] || {};
		const ergebnis = r.error ? 'fehler' : String(r.ergebnis || 'unbekannt');
		const k = `${a.aktion}:${ergebnis}`;
		zaehler[k] = (zaehler[k] || 0) + 1;
		if (r.error) fehler.push({ aktion: a.aktion, vorgangs_id: a.vorgangs_id, freigabe_id: a.freigabe_id || null });
	});
	return {
		aufgaben: (plan.aufgaben || []).length,
		ergebnisse: zaehler,
		fehler,
		uebersprungen: (plan.uebersprungen || []).length,
		verschoben: plan.verschoben || 0,
	};
}

// ---------------------------------------------------------------- Eskalation (Fall 2)

/**
 * Seit wann wartet der Vorgang? Erste versendete Rückfrage der aktuellen Runde, sonst die jüngste versendete
 * Nachricht. Liefert ganze Tage oder null, wenn kein Versand bekannt ist.
 */
function tageOhneReaktion(vorgang, gesendete, jetzt) {
	const liste = (gesendete || []).filter((f) => f && f.status === 'gesendet' && Number.isFinite(ms(f.gesendet_am)));
	const runde = Number(vorgang.rundenzaehler || 0);
	const dieseRunde = liste.filter((f) => f.art === 'rueckfrage' && Number(f.runde) === runde);
	let start = NaN;
	if (dieseRunde.length) start = Math.min(...dieseRunde.map((f) => ms(f.gesendet_am)));
	else if (liste.length) start = Math.max(...liste.map((f) => ms(f.gesendet_am)));
	if (!Number.isFinite(start)) return null;
	return Math.max(0, Math.floor((ms(jetzt) - start) / 86400000));
}

function esc(s) {
	return String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
}

function wertAus(daten, feld) {
	const d = daten && daten[feld];
	if (d === null || d === undefined) return '';
	return typeof d === 'object' ? String(d.wert ?? '') : String(d);
}

/** Teams-Nachricht an die Mitarbeiter (Masterprompt Fall 2) mit Kontaktdaten aus dem Vorgang. */
function meldungKeineReaktion({ vorgang, tage, erinnerungen, fehlende, daten, telefonFeld = 'Telefon' }) {
	const name = vorgang.absender_name ? `${vorgang.absender_name} ` : '';
	const seit = tage === null || tage === undefined ? 'seit längerer Zeit' : tage === 1 ? 'seit 1 Tag' : `seit ${tage} Tagen`;
	const tel = wertAus(daten, telefonFeld);
	const offen = (fehlende || []).map((f) => esc(f.anzeigename || f.feldname)).join(', ');
	return `<b>Kunde reagiert nicht – bitte telefonisch kontaktieren</b><br>Vorgang: <b>${esc(vorgang.vorgangs_id)}</b><br>` +
		`Kunde ${esc(name)}(${esc(vorgang.absender_adresse)}) reagiert ${esc(seit)} nicht auf Nachfragen (${Number(erinnerungen || 0)} Erinnerung(en) gesendet).<br>` +
		`Betreff: ${esc(vorgang.betreff)}${tel ? `<br>Telefon: ${esc(tel)}` : ''}${offen ? `<br>Noch offen: ${offen}` : ''}` +
		'<br>Es gehen keine automatischen Nachfragen mehr raus. Der Vorgang steht auf "Eskaliert / Manuell".';
}

// ---------------------------------------------------------------- Freigabe erinnern / erneuern

/**
 * Prüft, ob die Aufgabe für diese Freigabe noch gilt, und liefert die zu schreibenden Daten.
 * aktion: freigabe_erinnerung (neue Links zusätzlich, alte bleiben gültig)
 *         freigabe_erneuern   (neue Ablaufzeit, alle bisherigen Links werden ungültig)
 */
function freigabeAuffrischen({ aktion, freigabe, config, jetzt }) {
	if (!freigabe || freigabe.status !== 'offen') return { ok: false, grund: 'nicht_mehr_offen' };
	const t = ms(jetzt);
	const abgelaufen = ms(freigabe.ablauf) <= t;
	if (aktion === 'freigabe_erneuern') {
		if (!abgelaufen) return { ok: false, grund: 'nicht_abgelaufen' };
		const ablauf = new Date(t + Number(config.freigabe_ablauf_stunden) * 3600000).toISOString();
		return { ok: true, alteLinksSperren: true, ablauf, daten: { ablauf, erneuert_am: new Date(t).toISOString(), erinnert_am: null } };
	}
	if (aktion === 'freigabe_erinnerung') {
		if (abgelaufen) return { ok: false, grund: 'abgelaufen' };
		if (freigabe.erinnert_am) return { ok: false, grund: 'schon_erinnert' };
		return { ok: true, alteLinksSperren: false, ablauf: new Date(ms(freigabe.ablauf)).toISOString(), daten: { erinnert_am: new Date(t).toISOString() } };
	}
	return { ok: false, grund: 'unbekannte_aktion' };
}

module.exports = {
	LOCK_SCHLUESSEL, LOCK_MINUTEN, MAX_AUFGABEN, EPOCHE, PRIORITAET,
	planen, lockHolen, lockFreigeben, laufAuswerten, tageOhneReaktion, meldungKeineReaktion, freigabeAuffrischen,
};
return module.exports;
})();
// ===== Ende src/nachfassen.js =====

// ----- Node-Logik -----
const l = $input.first().json;
return [{ json: nachfassen.lockHolen(l.lauf_id, l.echt) }];

// ----- Node-Logik -----
const z = $input.first().json;
const fehlt = !(z && z.id !== undefined);
// Keine personenbezogenen Daten: nur Lauf-IDs und Zeitpunkte.
return [{ json: { ergebnis: fehlt ? 'lock_zeile_angelegt' : 'uebersprungen_lauf_aktiv', anlegen: fehlt, aktiver_lauf: fehlt ? null : z.lock_durch, lock_bis: fehlt ? null : z.lock_bis } }];

// ===== eingebettet aus src/nachfassen.js – nicht hier bearbeiten, sondern im Repo (npm run build) =====
const nachfassen = (() => {
const module = { exports: {} };
// Phase E (Masterprompt Workflow 4, Bauplan 2.2/6): Nachfassen beim Kunden, Eskalation, Erinnerung an Freigeber
// und Erneuerung abgelaufener Freigabe-Links. Reine Planungslogik: EPA-04 liest Vorgänge, offene Freigaben und
// Configs, dieses Modul entscheidet, was zu tun ist. Ausgeführt wird jede Aufgabe einzeln in "EPA SW Nachfassen".
// Es wird nie automatisch an Kunden gesendet: Eine Erinnerung an den Kunden ist immer ein Entwurf mit Freigabe.

const LOCK_SCHLUESSEL = 'epa04_lauf';
const LOCK_MINUTEN = 55;
const MAX_AUFGABEN = 50;
const EPOCHE = '1970-01-01T00:00:00.000Z';
const WARTEN = 'Warten auf Kunde';

// Reihenfolge, falls mehr Aufgaben anfallen als ein Lauf abarbeitet (Rest folgt im nächsten Lauf).
const PRIORITAET = Object.freeze({ eskalation: 1, erinnerung: 2, freigabe_erneuern: 3, freigabe_erinnerung: 4 });

function ms(t) {
	if (t === null || t === undefined || t === '') return NaN;
	const x = new Date(t).getTime();
	return Number.isFinite(x) ? x : NaN;
}

/**
 * Plant die Aufgaben eines Laufs.
 * @param {object} p
 * @param {object[]} p.vorgaenge  Zeilen aus epa_vorgaenge (Status "Warten auf Kunde")
 * @param {object[]} p.freigaben  Zeilen aus epa_freigaben (Status "offen")
 * @param {object} p.configs      kunde_id -> geprüfte Config; null = Kunde inaktiv; fehlt = Config ungültig
 * @param {string} p.jetzt        ISO-Zeitpunkt
 * @param {object} p.fristen      Modul src/fristen.js (im Code-Node eingebettet)
 * @returns {{ aufgaben: object[], uebersprungen: object[], verschoben: number }}
 */
function planen({ vorgaenge, freigaben, configs, jetzt, fristen, max = MAX_AUFGABEN }) {
	const jetztMs = ms(jetzt);
	if (!Number.isFinite(jetztMs)) throw new Error(`Ungültiger Zeitpunkt "${jetzt}"`);
	const aufgaben = [];
	const uebersprungen = [];
	const imDienst = {};
	const geschaeftszeit = (kunde, c) => {
		if (!(kunde in imDienst)) imDienst[kunde] = fristen.istGeschaeftszeit(jetzt, c);
		return imDienst[kunde];
	};

	for (const v of vorgaenge || []) {
		if (!v || v.status !== WARTEN) continue;
		const frist = ms(v.antwort_frist);
		if (!Number.isFinite(frist) || frist >= jetztMs) continue;
		const ref = { kunde_id: v.kunde_id, vorgangs_id: v.vorgangs_id };
		const c = configs[v.kunde_id];
		if (!c) {
			uebersprungen.push({ ...ref, grund: c === null ? 'kunde_inaktiv' : 'keine_gueltige_config' });
			continue;
		}
		if (!geschaeftszeit(v.kunde_id, c)) {
			uebersprungen.push({ ...ref, grund: 'ausserhalb_geschaeftszeit' });
			continue;
		}
		const gesendet = Number(v.erinnerungen_gesendet || 0);
		const erlaubt = Number(c.anzahl_erinnerungen || 0);
		aufgaben.push({
			aktion: gesendet < erlaubt ? 'erinnerung' : 'eskalation',
			...ref,
			freigabe_id: '',
			version: v.version ?? null,
			erinnerungen_gesendet: gesendet,
		});
	}

	for (const f of freigaben || []) {
		if (!f || f.status !== 'offen') continue;
		const ref = { kunde_id: f.kunde_id, vorgangs_id: f.vorgangs_id, freigabe_id: f.freigabe_id };
		const c = configs[f.kunde_id];
		if (!c) {
			uebersprungen.push({ ...ref, grund: c === null ? 'kunde_inaktiv' : 'keine_gueltige_config' });
			continue;
		}
		const abgelaufen = ms(f.ablauf) <= jetztMs;
		let erinnern = false;
		if (!abgelaufen && !f.erinnert_am && Number(c.freigabe_erinnerung_stunden) > 0) {
			const basis = f.erneuert_am || f.createdAt;
			if (Number.isFinite(ms(basis))) erinnern = ms(fristen.berechneFrist(new Date(basis).toISOString(), c.freigabe_erinnerung_stunden, c)) <= jetztMs;
		}
		if (!abgelaufen && !erinnern) continue;
		if (!geschaeftszeit(f.kunde_id, c)) {
			uebersprungen.push({ ...ref, grund: 'ausserhalb_geschaeftszeit' });
			continue;
		}
		aufgaben.push({ aktion: abgelaufen ? 'freigabe_erneuern' : 'freigabe_erinnerung', ...ref, version: null, erinnerungen_gesendet: null });
	}

	aufgaben.sort((a, b) => PRIORITAET[a.aktion] - PRIORITAET[b.aktion]);
	return { aufgaben: aufgaben.slice(0, max), uebersprungen, verschoben: Math.max(0, aufgaben.length - max) };
}

// ---------------------------------------------------------------- Lauf-Lock (Tabelle epa_system_status)

function lockHolen(laufId, jetztEcht) {
	const t = ms(jetztEcht);
	return {
		lock_bis: new Date(t + LOCK_MINUTEN * 60000).toISOString(),
		lock_durch: String(laufId),
		letzter_start: new Date(t).toISOString(),
	};
}

function lockFreigeben(jetztEcht, ergebnis) {
	return {
		lock_bis: EPOCHE,
		lock_durch: '',
		letzter_lauf: new Date(ms(jetztEcht)).toISOString(),
		letztes_ergebnis: JSON.stringify(ergebnis || {}),
	};
}

/** Zusammenfassung eines Laufs, nur Zähler und IDs (keine personenbezogenen Daten). */
function laufAuswerten(plan, ergebnisse) {
	const zaehler = {};
	const fehler = [];
	(plan.aufgaben || []).forEach((a, i) => {
		const r = (ergebnisse || [])[i] || {};
		const ergebnis = r.error ? 'fehler' : String(r.ergebnis || 'unbekannt');
		const k = `${a.aktion}:${ergebnis}`;
		zaehler[k] = (zaehler[k] || 0) + 1;
		if (r.error) fehler.push({ aktion: a.aktion, vorgangs_id: a.vorgangs_id, freigabe_id: a.freigabe_id || null });
	});
	return {
		aufgaben: (plan.aufgaben || []).length,
		ergebnisse: zaehler,
		fehler,
		uebersprungen: (plan.uebersprungen || []).length,
		verschoben: plan.verschoben || 0,
	};
}

// ---------------------------------------------------------------- Eskalation (Fall 2)

/**
 * Seit wann wartet der Vorgang? Erste versendete Rückfrage der aktuellen Runde, sonst die jüngste versendete
 * Nachricht. Liefert ganze Tage oder null, wenn kein Versand bekannt ist.
 */
function tageOhneReaktion(vorgang, gesendete, jetzt) {
	const liste = (gesendete || []).filter((f) => f && f.status === 'gesendet' && Number.isFinite(ms(f.gesendet_am)));
	const runde = Number(vorgang.rundenzaehler || 0);
	const dieseRunde = liste.filter((f) => f.art === 'rueckfrage' && Number(f.runde) === runde);
	let start = NaN;
	if (dieseRunde.length) start = Math.min(...dieseRunde.map((f) => ms(f.gesendet_am)));
	else if (liste.length) start = Math.max(...liste.map((f) => ms(f.gesendet_am)));
	if (!Number.isFinite(start)) return null;
	return Math.max(0, Math.floor((ms(jetzt) - start) / 86400000));
}

function esc(s) {
	return String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
}

function wertAus(daten, feld) {
	const d = daten && daten[feld];
	if (d === null || d === undefined) return '';
	return typeof d === 'object' ? String(d.wert ?? '') : String(d);
}

/** Teams-Nachricht an die Mitarbeiter (Masterprompt Fall 2) mit Kontaktdaten aus dem Vorgang. */
function meldungKeineReaktion({ vorgang, tage, erinnerungen, fehlende, daten, telefonFeld = 'Telefon' }) {
	const name = vorgang.absender_name ? `${vorgang.absender_name} ` : '';
	const seit = tage === null || tage === undefined ? 'seit längerer Zeit' : tage === 1 ? 'seit 1 Tag' : `seit ${tage} Tagen`;
	const tel = wertAus(daten, telefonFeld);
	const offen = (fehlende || []).map((f) => esc(f.anzeigename || f.feldname)).join(', ');
	return `<b>Kunde reagiert nicht – bitte telefonisch kontaktieren</b><br>Vorgang: <b>${esc(vorgang.vorgangs_id)}</b><br>` +
		`Kunde ${esc(name)}(${esc(vorgang.absender_adresse)}) reagiert ${esc(seit)} nicht auf Nachfragen (${Number(erinnerungen || 0)} Erinnerung(en) gesendet).<br>` +
		`Betreff: ${esc(vorgang.betreff)}${tel ? `<br>Telefon: ${esc(tel)}` : ''}${offen ? `<br>Noch offen: ${offen}` : ''}` +
		'<br>Es gehen keine automatischen Nachfragen mehr raus. Der Vorgang steht auf "Eskaliert / Manuell".';
}

// ---------------------------------------------------------------- Freigabe erinnern / erneuern

/**
 * Prüft, ob die Aufgabe für diese Freigabe noch gilt, und liefert die zu schreibenden Daten.
 * aktion: freigabe_erinnerung (neue Links zusätzlich, alte bleiben gültig)
 *         freigabe_erneuern   (neue Ablaufzeit, alle bisherigen Links werden ungültig)
 */
function freigabeAuffrischen({ aktion, freigabe, config, jetzt }) {
	if (!freigabe || freigabe.status !== 'offen') return { ok: false, grund: 'nicht_mehr_offen' };
	const t = ms(jetzt);
	const abgelaufen = ms(freigabe.ablauf) <= t;
	if (aktion === 'freigabe_erneuern') {
		if (!abgelaufen) return { ok: false, grund: 'nicht_abgelaufen' };
		const ablauf = new Date(t + Number(config.freigabe_ablauf_stunden) * 3600000).toISOString();
		return { ok: true, alteLinksSperren: true, ablauf, daten: { ablauf, erneuert_am: new Date(t).toISOString(), erinnert_am: null } };
	}
	if (aktion === 'freigabe_erinnerung') {
		if (abgelaufen) return { ok: false, grund: 'abgelaufen' };
		if (freigabe.erinnert_am) return { ok: false, grund: 'schon_erinnert' };
		return { ok: true, alteLinksSperren: false, ablauf: new Date(ms(freigabe.ablauf)).toISOString(), daten: { erinnert_am: new Date(t).toISOString() } };
	}
	return { ok: false, grund: 'unbekannte_aktion' };
}

module.exports = {
	LOCK_SCHLUESSEL, LOCK_MINUTEN, MAX_AUFGABEN, EPOCHE, PRIORITAET,
	planen, lockHolen, lockFreigeben, laufAuswerten, tageOhneReaktion, meldungKeineReaktion, freigabeAuffrischen,
};
return module.exports;
})();
